add_action( 'woocommerce_thankyou', 'perfectpixel_auto_register_guest', 20 );

function perfectpixel_auto_register_guest( $order_id ) {
	$order = wc_get_order( $order_id );
	if ( ! $order || $order->get_customer_id() || $order->get_meta( '_perfectpixel_auto_registered' ) ) {
		return;
	}
	$email = $order->get_billing_email();
	if ( ! is_email( $email ) || email_exists( $email ) ) {
		return;
	}

	$user_id = wc_create_new_customer(
		$email,
		'',
		'',
		array(
			'first_name' => $order->get_billing_first_name(),
			'last_name'  => $order->get_billing_last_name(),
		)
	);
	if ( is_wp_error( $user_id ) ) {
		return;
	}

	$order->set_customer_id( $user_id );
	$order->update_meta_data( '_perfectpixel_auto_registered', 1 );
	$order->save();

	// Link earlier guest orders with the same email and copy the addresses to the new account.
	wc_update_new_customer_past_orders( $user_id );
	$customer = new WC_Customer( $user_id );
	foreach ( array( 'first_name', 'last_name', 'company', 'address_1', 'address_2', 'city', 'state', 'postcode', 'country', 'phone' ) as $field ) {
		$getter = 'get_billing_' . $field;
		$setter = 'set_billing_' . $field;
		$customer->$setter( $order->$getter() );
	}
	$customer->save();
}
